package com.example.starter.incident;

/**
 * 资源租约状态机：ACTIVE → RELEASED。
 * 到期不是租约的存储状态：ACTIVE 租约在当前时刻 >= expires_at 时视为已到期，
 * 由访问或命令按注入时钟即时判定，不做后台扫描。RELEASED 为终态。
 */
public enum AssignmentStatus {

    /** 生效中（是否已到期按 expires_at 与当前时刻判定）。 */
    ACTIVE,

    /** 已回收（任务完成或取消时释放资源）。 */
    RELEASED;
}

package com.example.starter.incident;

/**
 * 资源租约证据事件类型。证据只追加、不改写，按 id 升序排列。
 */
public enum ResourceEventType {

    /** 分配：固化资源、初始授权版本、分配时刻与分配人。 */
    ASSIGN,

    /** 续期：固化旧/新授权版本、续期时刻与续期人。 */
    RENEW,

    /** 到期检测：命令路径首次按时钟判定到期并将任务置为 AUTHORIZATION_EXPIRED。 */
    EXPIRE,

    /** 执行拦截：开始/继续执行/完成因授权到期被拒绝。 */
    EXECUTE_DENIED,

    /** 资源回收：任务完成或取消时释放租约。 */
    RELEASE;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 任务资源租约实体，对应 task_resource_assignments 表。
 * 授权有效期为左闭右开区间 [assignedAt, expiresAt)，UTC 口径；
 * releasedBy/releasedAt 仅 RELEASED 有值，否则为空。到期为派生状态，不落库。
 */
public record ResourceAssignment(
        long id,
        long taskId,
        long incidentId,
        String resourceKey,
        int authorizationVersion,
        String assignedBy,
        Instant assignedAt,
        Instant expiresAt,
        AssignmentStatus status,
        String releasedBy,
        Instant releasedAt,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 按给定时刻判断授权是否已到期（左闭右开：当前时刻 >= expiresAt 即到期）。
     */
    public boolean expiredAt(Instant now) {
        return status == AssignmentStatus.ACTIVE && !now.isBefore(expiresAt);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 资源租约证据实体，对应 resource_assignment_events 表。
 * 只追加、不改写：后续任务修订或事件合并不改写原资源使用证据。
 * oldVersion 在 ASSIGN 时为空；newVersion 在 EXPIRE/EXECUTE_DENIED/RELEASE 时为空。
 */
public record ResourceEvent(
        long id,
        long assignmentId,
        long incidentId,
        long taskId,
        String resourceKey,
        ResourceEventType eventType,
        Integer oldVersion,
        Integer newVersion,
        String actor,
        Instant occurredAt,
        String detail) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 任务执行日志实体，对应 task_execution_logs 表。
 * 授权到期后日志保留，不改写；entryType 为 START 或 PROGRESS。
 */
public record TaskExecutionLog(
        long id,
        long taskId,
        String entryType,
        String note,
        String actor,
        Instant occurredAt) {
}

