                    throw ApiException.conflict("任务尚未开始执行，不能记录继续执行");
                }
                evidence.insertExecutionLog(new TaskExecutionLog(0L, task.id(), "PROGRESS",
                        note, actor, now()));
                return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
            });
}

